#!/usr/bin/env python3
"""The platform's CI repositories (clusters/<cluster>/ci/): check the layout
and write the generated files.

    python3 tools/ci.py generate   # write the generated files, make missing Secrets
    python3 tools/ci.py check      # what the merge check runs: fails when a
                                  # file is invalid or a generated file stale

Layout (docs/reference/ci-repository.md):

    clusters/<cluster>/ci/<name>/repository.yaml   a repository whose pipelines
                                  Pipelines-as-Code runs: repository, namespace,
                                  pipelinesAsCode, forgejo, harbor (base/ci-repository)
    clusters/<cluster>/ci/<name>/*.enc.yaml        its Secrets (SOPS)
    clusters/<cluster>/ci/<name>/kustomization.yaml, secret-generator.yaml
                                  generated: the Secrets through KSOPS

Secrets every repository needs, made by `generate` when missing (the merge
check runs it and commits the result; sops encrypts for the public keys of
.sops.yaml, set SOPS to the binary if it is not on PATH; GITOPS_ROOT: the
checkout to work on):
- forgejo-pac.enc.yaml: pac-bot's token (PAC_BOT_TOKEN_FILE, default
  /root/lab/lab-secrets/forgejo/pac-bot-token) and the webhook's secret;
- forgejo-webhook.enc.yaml (with forgejo:): the webhook's config for
  Crossplane, the same secret (made with forgejo-pac.enc.yaml; added later,
  it is read from it, which needs a private key: SOPS_AGE_KEY_FILE);
- registry-push.enc.yaml (with harbor:): the robot's name and a password Harbor
  accepts (upper and lower case, a digit).
Other *.enc.yaml files in the folder (e.g. argocd-preview) are listed too.
"""
import os
import secrets
import string
import subprocess
import sys
from pathlib import Path

import yaml

# The gitops checkout: GITOPS_ROOT, or the repository this script is in.
ROOT = Path(os.environ.get("GITOPS_ROOT") or Path(__file__).resolve().parent.parent).resolve()
# HEADER: first lines of every generated file. PAC_WEBHOOK_URL: Pipelines-as-Code's
# controller on cluster {cluster}, the target of the Forgejo webhook.
HEADER = "# Generated by tools/ci.py: do not edit, run 'python3 tools/ci.py generate'\n# (the merge check compares).\n"
PAC_WEBHOOK_URL = "https://pac.apps.{cluster}.example.org"


def folders() -> list[tuple[str, Path]]:
    """Return (cluster name, folder) of every CI repository folder, clusters/<cluster>/ci/<name>, sorted."""
    out = []
    for c in sorted((ROOT / "clusters").iterdir()):
        if (c / "ci").is_dir():
            out += [(c.name, d) for d in sorted((c / "ci").iterdir()) if d.is_dir()]
    return out


def load(d: Path, errors: list[str]) -> dict | None:
    """Return the parsed repository.yaml of folder d.

    Returns None, with a message appended to errors, when the file is missing,
    is not valid YAML, is not a mapping or has no namespace.
    """
    rel = d.relative_to(ROOT)
    f = d / "repository.yaml"
    if not f.is_file():
        errors.append(f"{rel}: no repository.yaml")
        return None
    try:
        v = yaml.safe_load(f.read_text()) or {}
    except yaml.YAMLError as e:
        errors.append(f"{rel}/repository.yaml: {e}")
        return None
    if not isinstance(v, dict):
        errors.append(f"{rel}/repository.yaml: not a mapping")
        return None
    if not v.get("namespace"):
        errors.append(f"{rel}/repository.yaml: namespace is required")
        return None
    return v


def required(v: dict) -> list[str]:
    """Return the Secret files a repository with values v must have (see the module docstring)."""
    need = ["forgejo-pac.enc.yaml"]
    if v.get("forgejo"):
        need.append("forgejo-webhook.enc.yaml")
    if v.get("harbor"):
        need.append("registry-push.enc.yaml")
    return need


def static_files(name: str, d: Path) -> dict[str, str]:
    """Return the generated files of repository name, by file name, with their expected content.

    The KSOPS generator lists every *.enc.yaml present in d, sorted, so call it
    after the Secrets are made.
    """
    encs = sorted(f.name for f in d.glob("*.enc.yaml"))
    return {
        "kustomization.yaml": HEADER + f"""# The Secrets of CI repository {name} (SOPS, KSOPS); the rest comes from the
# chart base/ci-repository with repository.yaml as values (ApplicationSet
# ci-repositories).
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
generators:
  - secret-generator.yaml
""",
        "secret-generator.yaml": HEADER + f"""apiVersion: viaduct.ai/v1
kind: ksops
metadata:
  name: ci-{name}-secrets
  annotations:
    config.kubernetes.io/function: |
      exec:
        path: ksops
files:
""" + "".join(f"  - {e}\n" for e in encs),
    }


def sops(*args: str, stdin: str | None = None, cwd: Path) -> str:
    """Run sops (SOPS, default "sops" on PATH) with args in cwd and return its stdout; exit if it fails."""
    out = subprocess.run([os.environ.get("SOPS", "sops"), *args], input=stdin, capture_output=True, text=True, cwd=cwd)
    if out.returncode != 0:
        raise SystemExit(f"sops {' '.join(args[:1])} failed: {out.stderr.strip()}")
    return out.stdout


def encrypt(cluster_dir: Path, target: Path, secret: dict) -> None:
    """Write secret to target, encrypted with the creation rules of cluster_dir's .sops.yaml.

    --filename-override gives sops target's path, so that the rules' path_regex
    applies although the plaintext comes from stdin.
    """
    rel = str(target.relative_to(cluster_dir))
    target.write_text(sops("encrypt", "--input-type", "yaml", "--output-type", "yaml", "--filename-override", rel,
                           "/dev/stdin", stdin=yaml.safe_dump(secret, sort_keys=False), cwd=cluster_dir))


def harbor_password() -> str:
    """Return a random 32-character alphanumeric password with an upper case letter,
    a lower case letter and a digit, as Harbor requires (draws again until it has all three)."""
    alphabet = string.ascii_letters + string.digits
    while True:
        p = "".join(secrets.choice(alphabet) for _ in range(32))
        if any(c.isupper() for c in p) and any(c.islower() for c in p) and any(c.isdigit() for c in p):
            return p


def secret(name: str, ns: str, data: dict) -> dict:
    """Return a Secret manifest named name in namespace ns holding data as stringData."""
    return {"apiVersion": "v1", "kind": "Secret", "metadata": {"name": name, "namespace": ns}, "stringData": data}


def make_secrets(cluster: str, d: Path, v: dict) -> None:
    """Write the missing Secret files of repository folder d (values v); never replace one.

    Reads pac-bot's token from PAC_BOT_TOKEN_FILE for a new forgejo-pac. The
    webhook Secret must carry the same secret as forgejo-pac: a new one is
    taken from the forgejo-pac made in the same call, otherwise forgejo-pac is
    decrypted, which needs SOPS_AGE_KEY_FILE (exits without it).
    """
    cdir, ns = ROOT / "clusters" / cluster, v["namespace"]
    pac = d / "forgejo-pac.enc.yaml"
    hook = d / "forgejo-webhook.enc.yaml"
    want_hook = bool(v.get("forgejo")) and not hook.is_file()
    s = None
    if not pac.is_file():
        token = Path(os.environ.get("PAC_BOT_TOKEN_FILE", "/root/lab/lab-secrets/forgejo/pac-bot-token")).read_text().strip()
        s = secrets.token_hex(32)
        encrypt(cdir, pac, secret("forgejo-pac", ns, {"provider.token": token, "webhook.secret": s}))
        print(f"wrote {pac.relative_to(ROOT)} (new webhook secret)")
    if want_hook:
        if s is None:
            if not os.environ.get("SOPS_AGE_KEY_FILE"):
                raise SystemExit(f"{hook.relative_to(ROOT)}: forgejo-pac.enc.yaml exists, its webhook secret is "
                                 "needed: run 'tools/ci.py generate' with SOPS_AGE_KEY_FILE (the admin key)")
            s = yaml.safe_load(sops("decrypt", str(pac.relative_to(cdir)), cwd=cdir))["stringData"]["webhook.secret"]
        encrypt(cdir, hook, secret("forgejo-webhook", ns, {"url": PAC_WEBHOOK_URL.format(cluster=cluster),
                                                           "content_type": "json", "secret": s}))
        print(f"wrote {hook.relative_to(ROOT)}")
    push = d / "registry-push.enc.yaml"
    hb = v.get("harbor") or {}
    if hb and not push.is_file():
        encrypt(cdir, push, secret("registry-push", ns, {"registry": "registry.example.org",
                                                         "username": f"robot${hb['project']}+{hb['robot']}",
                                                         "password": harbor_password()}))
        print(f"wrote {push.relative_to(ROOT)} (new robot password)")


def main(argv: list[str]) -> int:
    """Run `generate` or `check` over every CI repository folder.

    Returns 2 (usage on stderr) for other arguments, 1 if any error was found,
    else 0. `generate` makes missing Secrets and rewrites stale generated files
    first, so it reports only what it cannot fix; both commands report
    duplicate namespaces and stray files.
    """
    if argv not in (["generate"], ["check"]):
        print(__doc__, file=sys.stderr)
        return 2
    write, errors, n = argv == ["generate"], [], 0
    namespaces: dict[str, str] = {}
    for cluster, d in folders():
        v = load(d, errors)
        if v is None:
            continue
        n += 1
        rel = d.relative_to(ROOT)
        if v["namespace"] in namespaces:
            errors.append(f"{rel}: namespace {v['namespace']} is {namespaces[v['namespace']]}'s already")
        namespaces[v["namespace"]] = str(rel)
        if write:
            make_secrets(cluster, d, v)
        for need in required(v):
            if not (d / need).is_file():
                errors.append(f"{rel}/{need}: missing: run 'python3 tools/ci.py generate' and commit")
        for fname, content in static_files(d.name, d).items():
            f = d / fname
            if f.is_file() and f.read_text() == content:
                continue
            if write:
                f.write_text(content)
                print(f"wrote {f.relative_to(ROOT)}")
            else:
                errors.append(f"{f.relative_to(ROOT)} is not current: run 'python3 tools/ci.py generate' and commit")
        for f in sorted(d.iterdir()):
            if f.name not in ("repository.yaml", "kustomization.yaml", "secret-generator.yaml") and not f.name.endswith(".enc.yaml"):
                errors.append(f"{f.relative_to(ROOT)}: only repository.yaml, *.enc.yaml and generated files belong here")
    for e in errors:
        print(f"ERROR: {e}", file=sys.stderr)
    if not errors:
        print(f"CI repositories: {n}, all current")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
